-- public.altar_on_deed(p_world uuid, p_uid uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.altar_on_deed(p_world uuid, p_uid uuid, p_x integer, p_y integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select exists (
    select 1 from deed_here(p_world, p_uid, p_x, p_y) d
      join placed pl on pl.world_id = p_world and pl.kind = 'furniture'
                    and pl.x between d.x - d.radius and d.x + d.radius
                    and pl.y between d.y - d.radius and d.y + d.radius
     where d.world_id is not null
       and pl.sub in (select f.id from furniture_def f where f.altar))
$function$
